<script lang="ts">import{api,rows,text,number,type Row}from'../lib/api';import{tr}from'../lib/i18n';export let data:Row={};export let onreload:()=>void;export let onerror:(e:any)=>void;let editing='';let draft:Row={};let busy=false;const fields=['input','cache_read','cache_write','output'];function edit(row:Row){editing=row.model;draft=Object.fromEntries(fields.map(k=>[k,row[k]??'']))}async function save(reset=false){busy=true;try{await api('SavePrice',editing,reset?{}:Object.fromEntries(fields.map(k=>[k,draft[k]===''?null:Number(draft[k])])));editing='';onreload()}catch(e){onerror(e)}finally{busy=false}}function price(v:any){const n=number(v);return n===null?'—':n.toLocaleString(undefined,{maximumFractionDigits:6})}</script>
<div class="row between"><p class="muted">{tr('每百万 Token / USD')} · {text(data.basis)}</p><small class="muted">{text(data.version)}</small></div><section class="surface table-scroll"><table class="price-table"><thead><tr>{#each ['模型','输入','缓存读取','缓存写入','输出','速度','来源'] as label}<th>{tr(label)}</th>{/each}</tr></thead><tbody>{#each rows(data.rows) as p}<tr><td><strong>{text(p.model)}</strong><small class="muted">{text(p.condition,'')}{p.threshold?' · '+p.threshold:''}</small></td>{#each fields as key}<td>{price(p[key])}</td>{/each}<td>{text(p.service_tier)}</td><td>{#if (!p.service_tier||['standard','default'].includes(p.service_tier))&&!Number(p.threshold)}<button class="quiet" onclick={()=>edit(p)}>{tr('编辑')}</button>{/if}{#if p.source}<small>{text(p.source)}</small>{/if}</td></tr>{/each}</tbody></table>{#if !rows(data.rows).length}<div class="empty">{tr('暂无数据')}</div>{/if}</section>{#if editing}<div class="modal-backdrop"><form class="modal" onsubmit={e=>{e.preventDefault();void save()}}><h2>{editing}</h2><p class="muted">{tr('每百万 Token / USD')}</p>{#each fields as key,i}<label class="field"><span>{tr(['输入','缓存读取','缓存写入','输出'][i])}</span><input type="number" step="any" min="0" bind:value={draft[key]} placeholder="—"/></label>{/each}<div class="row"><button class="primary" disabled={busy}>{tr('保存')}</button><button type="button" disabled={busy} onclick={()=>save(true)}>{tr('恢复目录价格')}</button><button type="button" onclick={()=>editing=''}>{tr('取消')}</button></div></form></div>{/if}
